var i=`0466-borek`;var t=`world-0466`;var a=`TR`;var o=`western-asia`;var r=8;var l=70;var s={en:`Börek`,ua:`Бьорек`};var g={en:`A traditional dish from Türkiye, centered on feta, spinach, chicken egg, phyllo pastry. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Туреччина. Основні складники: фета, шпинат, куряче яйце, тісто філо. Домашній варіант із кількостями продуктів за етапами приготування.`};var h=[{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:8,i:[[`feta`,230,`g`],[`spinach`,300,`g`],[`chicken-egg`,1,`pcs`]]},{en:`Layer the prepared elements evenly in the baking dish, spreading filling right to the edges.`,ua:`Викладіть підготовлені компоненти рівними шарами у формі, розподіляючи начинку до країв.`,t:[`layered-assembly`],m:13,i:[[`phyllo-pastry`,420,`g`],[`unsalted-butter`,100,`g`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:15,i:[]},{en:`Bake in a preheated 180°C oven for about 34 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 34 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:34,i:[]}];var d={slug:i,id:t,country:`TR`,region:o,servings:8,minutes:70,title:s,text:g,steps:h};export{a as country,d as default,t as id,l as minutes,o as region,r as servings,i as slug,h as steps,g as text,s as title};